// 인사이트(/insight). 영역별로 이어지는 묶음 글. 읽는 순서(편 번호)대로 넣는다.
// 11-02 운영과 유지보수 15편부터. 목차는 01_Work/01_Active/곰파트너-마케팅/아티클/목차-운영과-유지보수.md
// 재료는 실제 경력의 익명 장면만 쓴다. 지어낸 사례 금지, 기관명과 현 직장 단서 금지.
export interface InsightBlock {
  h?: string;
  p?: string[];
  /** 굵은 머리말과 설명. 순서가 있는 목록 */
  steps?: { b: string; t: string }[];
  /** 표가 있으면 p는 표 아래에 나온다. 표 위에 둘 글은 앞 블록으로 나눈다 */
  table?: { head: string[]; rows: string[][] };
  /** 명령과 출력 인용(실측 그대로) */
  code?: string;
}

export interface Insight {
  slug: string;
  /** YYYY-MM-DD */
  date: string;
  series: string;
  /** 묶음 안 순서 */
  no: number;
  title: string;
  /** 목록과 검색 설명에 쓰는 한 줄 요약 */
  summary: string;
  blocks: InsightBlock[];
  /** 다음 편 예고 한두 문장 */
  next?: string;
  /** 글 끝에 잇는 유지보수 메뉴 */
  service: { href: string; label: string };
  /** 대표 이미지 1200x675. 공유 미리보기, 구글 디스커버, 구조화 데이터용. 새 글을 넣으면 node scripts/insight-cards.mjs 로 만든다 */
  image: { src: string; alt: string };
}

